from .money import (
    _MAX_CENTS,
    _amount_to_cents,
    _decimal_from_cents,
    format_amount,
)


def make_invoice(amounts):
    if isinstance(amounts, (str, bytes, bytearray)):
        raise ValueError("amounts must be a list of amounts")
    try:
        items = list(amounts)
    except TypeError:
        raise ValueError("amounts must be a list of amounts") from None

    total_cents = 0
    for item in items:
        total_cents += _amount_to_cents(item)

    if total_cents > _MAX_CENTS:
        raise ValueError("invoice total must not exceed 1000000.00")

    total = _decimal_from_cents(total_cents)
    return {"total": format_amount(total), "count": len(items)}

